-- Version 1 of the database. Do not edit this file after it has shipped:
-- add a new entry to MIGRATIONS in db.py instead.

CREATE TABLE kinds (
    id        INTEGER PRIMARY KEY,
    name      TEXT NOT NULL UNIQUE,
    position  INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE items (
    id              INTEGER PRIMARY KEY,
    title           TEXT NOT NULL,
    notes           TEXT NOT NULL DEFAULT '',
    -- NULL until the item has been sized. Only quick and task can be planned.
    size            TEXT CHECK (size IN ('quick', 'task', 'project', 'big_ticket')),
    kind_id         INTEGER REFERENCES kinds(id),
    status          TEXT NOT NULL DEFAULT 'inbox'
                    CHECK (status IN ('inbox', 'backlog', 'someday', 'planned', 'done', 'dropped')),
    -- The day (YYYY-MM-DD) the item is planned for. Kept after it is done,
    -- so a finished item still uses its slot in the daily cap.
    planned_date    TEXT,
    -- 1 when a quick sits in that day's quick block instead of the quick lane.
    in_quick_block  INTEGER NOT NULL DEFAULT 0,
    -- Real external deadline only (YYYY-MM-DD).
    hard_date       TEXT,
    bump_count      INTEGER NOT NULL DEFAULT 0,
    -- The project this item is a next step of.
    parent_id       INTEGER REFERENCES items(id),
    -- Manual order inside whatever list the item is shown in.
    position        INTEGER NOT NULL DEFAULT 0,
    source_ref      TEXT,
    created_at      TEXT NOT NULL,
    completed_at    TEXT
);

CREATE INDEX items_status ON items(status);
CREATE INDEX items_planned_date ON items(planned_date);
CREATE INDEX items_parent ON items(parent_id);

-- One row per day that has a quick block. The block uses one task slot.
CREATE TABLE quick_blocks (
    day TEXT PRIMARY KEY
);

-- Calendar feeds. The url is a secret: never show it and never log it.
CREATE TABLE calendar_feeds (
    id     INTEGER PRIMARY KEY,
    label  TEXT NOT NULL,
    url    TEXT NOT NULL,
    mode   TEXT NOT NULL DEFAULT 'busy_only' CHECK (mode IN ('full', 'busy_only'))
);

CREATE TABLE settings (
    key    TEXT PRIMARY KEY,
    value  TEXT NOT NULL
);
